const user = $input.first().json;

if (!user.id || !user.active) {
  throw new Error('Invalid session.');
}

// Reuses this same get-contacts webhook for both the active list and the
// Archived tab:
//   GET /webhook/get-contacts?archived=false   (All Contacts / My Contacts)
//   GET /webhook/get-contacts?archived=true    (Archived tab)
const webhookQuery = $('Webhook').first().json.query || {};
const showArchived = String(webhookQuery.archived || '').toLowerCase() === 'true';
// ?id=123 narrows to a single contact — used by DealDetailModal (and
// anywhere else that only needs one row) instead of pulling + polling the
// entire contacts list just to find one by id.
const singleId = webhookQuery.id ? parseInt(webhookQuery.id, 10) : null;
// ?account_id=456 narrows to one company's contacts — used by
// CompanyDetailModal instead of pulling + polling the entire contacts
// list just to filter it client-side down to one company's rows.
const accountId = webhookQuery.account_id ? parseInt(webhookQuery.account_id, 10) : null;

// archived_by_name is only meaningful (and only joined) for the archived
// view — harmless left join either way, just always null when not archived.
// tags is embedded via json_agg so the Contacts table can render them
// without an extra get-entity-tags round trip per row (taggables/tags
// schema matches contacts-Tags System.json).
const sqlQuery = `
  SELECT c.*, co.name AS company_name, u.name AS owner_name,
         ab.name AS archived_by_name,
         (SELECT COALESCE(json_agg(json_build_object('id', t.id, 'name', t.name)), '[]'::json)
          FROM taggables tg JOIN tags t ON t.id = tg.tag_id
          WHERE tg.entity_type = 'contact' AND tg.entity_id = c.id) AS tags,
         GREATEST(c.updated_at, (SELECT MAX(created_at) FROM entity_activity_log WHERE entity_type = 'contact' AND entity_id = c.id)) AS last_activity_at
  FROM contacts c
  LEFT JOIN companies co ON co.id = c.account_id
  LEFT JOIN users u ON u.id = c.owner_id
  LEFT JOIN users ab ON ab.id = c.archived_by
  WHERE c.is_archived = $1
    AND ($2::int IS NULL OR c.id = $2)
    AND ($3::int IS NULL OR c.account_id = $3)
  ORDER BY c.id;
`;

return [{ json: { sqlQuery, queryParams: [showArchived, singleId, accountId] } }];

// alwaysOutputData on Execute Query emits one placeholder {} item when the
// query matched zero rows (e.g. every contact archived) — without this,
// zero rows meant zero items reached Respond, which sent a 0-byte body
// the frontend's res.json() couldn't parse, silently leaving the UI on
// stale cached data instead of showing an empty list.
const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
return [{ json: { rows } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
return [{ json: { token } }];

const r = $input.first().json;
if (!r.valid) throw new Error('Invalid session.');


return [{ json: { id: r.userId, role: r.role, name: r.user?.name, active: r.active } }];
